export const typeDefs = `#graphql
  type Profile {
    name: String!
    handle: String!
    tagline: String!
    bio: String!
    email: String!
    phone: String!
    whatsapp: String!
    instagram: String!
    location: String!
    deliveryDays: Int!
    skills: [String!]!
  }

  type WorkSample {
    id: ID!
    title: String!
    category: String!
    """Google Drive share link; clicking a card opens this."""
    videoUrl: String!
    """Thumbnail generated by Google Drive for the shared video."""
    thumbnailUrl: String!
    gradient: [String!]!
  }

  type Plan {
    name: String!
    badge: String
    videos: Int!
    priceUsd: Int!
    pricePerVideo: Float!
    deliveryDays: Int!
    features: [String!]!
  }

  type Service {
    icon: String!
    title: String!
    description: String!
  }

  type Faq {
    question: String!
    answer: String!
  }

  type Inquiry {
    id: ID!
    name: String!
    email: String!
    createdAt: String!
  }

  input InquiryInput {
    name: String!
    email: String!
    product: String
    message: String!
  }

  type Query {
    profile: Profile!
    works: [WorkSample!]!
    plans: [Plan!]!
    services: [Service!]!
    faqs: [Faq!]!
  }

  type Mutation {
    submitInquiry(input: InquiryInput!): Inquiry!
  }
`;
